function Game.prototype.jumpToNode(self, id)
    local snap = self.treeSnap[id]
    if snap == nil then
        return
    end
    if self.dialog:isOpen() or self.teleportT >= 0 then
        return
    end
    local prevSeen = self.state.storySeen
    local prevAsked = self.state.askedChoices
    local prevMemories = self.state.memories:slice()
    self.state = self:cloneLoopState(snap)
    for k in pairs(prevSeen) do
        self.state.storySeen[k] = true
    end
    for k in pairs(prevAsked) do
        self.state.askedChoices[k] = true
    end
    do
        local i = 0
        while i < #prevMemories do
            if self.state.memories:indexOf(prevMemories[i + 1]) < 0 then
                self.state.memories:push(prevMemories[i + 1])
            end
            i = i + 1
        end
    end
    self.mech.state = self.state
    self.mech:syncStones(Tower.pushStones)
    self.enemies:spawnAll(Tower.enemies, self.state.loopIndex)
    self.stealth:resetRuntime()
    __TS__ArraySetLength(self.qiShots, 0)
    self.attackApplied = false
    self.intentRegenT = 0
    self.bladeT = 0
    self.floor1Kill = false
    self.floor1Alert = false
    self.treeFloorSeen = {}
    self.treeGateSeen = {}
    self.treeDeathSeen = false
    self.treeJumpPending = true
    self:respawnAt(self.state.currentCheckpointId)
    self.mode = "rewind"
    self.rewindT = 0
    self.causFx:play("rewind", "时空回溯·跳回节点")
    self.hud:setRewind(0)
end
