        self.state.objective = "水已打好——去移树苗（x≈700），再种进枯坑（x≈1200）"
        return true
    end
    if not planted and Math:abs(px - 1200) < 100 then
        if self.state.flags.saplingTaken == true then
            self.state.flags.treePlanted = true
            self.state.flags.saplingTaken = false
            if self.state.flags.bucketFull == true then
                self.state.flags.bucketFull = false
            end
            self.mech:openGate("gate_ferry")
            if self.tree ~= nil then
                self.tree:addChoice("种下树苗")
            end
            self:logCause("枯坑种树·因果成立")
            self.causFx:play("grow", "种下·对岸月影同时落地")
            self.fx:spawnRing(
                px,
