                130,
                0.8
            )
            sfx("click", 1)
            self.state.objective = "树影成双——月华凝成新的月石（攀树梯而上，x≈1180 按 W）；渡口尽头的传送门亮起了"
            return true
        end
        self.state.objective = "枯坑沉默着……像在等一株树苗（西边有井，也有苗）"
        return true
