    if planted and self.state.flags.bucketFull == true and Math:abs(px - 1200) < 100 then
        self.state.flags.bucketFull = false
        self:logCause("月色浇灌·新苗抽枝")
        self.causFx:play("grow", "浇灌·月华入土")
