function Game.prototype.hintText(self)
    if self.mode == "confront" then
        return "走近沈砚：E 放下剑 · Q 以命换命 · J 剑锋相向 · Tab 手札"
    end
    if self.mode == "play" and (self:nearPortal(self.player.body.x, self.player.body.y) ~= nil or self.nearStoryId ~= nil) then
        return ""
    end
    if self.player.onLadder then
        return "W/S 攀爬 · 到顶后按 Space 跳向右侧平台"
    end
    return ""
end
function Game.prototype.makeNpcSprite(self, paths, parent, tag)
    local tex
    local used = ""
    for ____, p in ipairs(paths) do
        tex = Texture2D(p)
        if tex ~= nil then
            used = p
            break
        end
    end
    if tex == nil or used == "" then
        print((("[" .. tag) .. "] texture load failed: ") .. paths:join(" | "))
        return nil
    end
    print(((((((("[" .. tag) .. "] loaded ") .. used) .. " (") .. tostring(tex.width)) .. "x") .. tostring(tex.height)) .. ")")
    local sp = Sprite(tex)
    if sp == nil then
        return nil
    end
    local s = 90 / tex.height
    sp.scaleX = s
    sp.scaleY = s
    sp.anchor = Vec2(0.5, 0)
    sp.visible = false
    sp:addTo(parent)
    return sp
end
function Game.prototype.drawNpcs(self)
