            560,
            500,
            650,
            480,
            1900,
            460
        }
        local tops = Tower.TOPS
        local target = Math:min(
            self:shenProgress(),
            #xs - 1
        )
        if target < self.shenShownIdx then
            self.shenShownIdx = target
        elseif target > self.shenShownIdx then
            local nx = xs[target + 1]
            local ny = tops[Math:min(target, #tops - 2) + 1]
