                self.shenShownIdx = target
            end
        end
        local idx = Math:min(self.shenShownIdx, target)
        sx = xs[idx + 1]
        sy = tops[Math:min(idx, #tops - 2) + 1]
        hideShen = Math:min(idx, #tops - 2) == 3 or Math:min(idx, #tops - 2) == 5
    end
