                                q.x + q.dir * (ox + R * Math:cos(t)),
                                q.y + wob + R * Math:sin(t)
                            ))
                            k = k + 1
                        end
                    end
                    local c2 = -0.6 * R
                    local ri = 1.2266 * R
                    local aIn = 0.9425
                    do
                        local k = 0
                        while k <= 10 do
                            local t = -aIn + 2 * aIn * k / 10
                            pts:push(Vec2(
                                q.x + q.dir * (ox + c2 + ri * Math:cos(t)),
                                q.y + wob + ri * Math:sin(t)
                            ))
                            k = k + 1
                        end
                    end
                    return pts
                end
                d:drawPolygon(
                    buildCres(0.72, -38),
                    Color(CYAN.r, CYAN.g, CYAN.b, 42)
